import { _decorator, Color, Component, Graphics, Node } from 'cc';
import type { EntityView } from '../../Engine/ViewRegistry';
import type { Entity } from '../../Engine/Entity';
import type { Plane } from '../Entity/Plane';
const { ccclass, } = _decorator;

@ccclass('PlayerView')
export class PlayerView extends Component implements EntityView{

    private _plane: Plane | null = null;

    onLoad() {
    const g = this.node.addComponent(Graphics);
    g.fillColor = new Color(80, 200, 255, 255);
    // 朝上的三角形，表示玩家飞机
    g.moveTo(0, 20);
    g.lineTo(-15, -10);
    g.lineTo(15, -10);
    g.close();
    g.fill();
}

    bind(entity: Entity): void{
        this._plane = entity as Plane;
        this.sync(0);
    }

    sync(dt: number): void{
        if (!this._plane) return;
        this.node.setPosition(this._plane.x, this._plane.y);
    }

    unbind(): void{
        this._plane = null;
    }

}


